.darma-loader-darma-b12-inchworm-crawl { --accent: var(--loader-color, #65a30d); --accent-2: var(--loader-secondary-color, #a3e635); width: var(--loader-size, 116px); height: calc(var(--loader-size, 116px) * .38); position: relative; }
.darma-loader-darma-b12-inchworm-crawl::after { content: ''; position: absolute; left: 0; bottom: 0; width: 100%; height: 6%; border-radius: 999px; background: #cbd5e1; }
.darma-loader-darma-b12-inchworm-crawl .darma-loader-darma-b12-inchworm-crawl__worm { position: absolute; bottom: 6%; border-radius: 999px 999px 40% 40%; background: linear-gradient(var(--accent-2), var(--accent)); animation: darma-loader-darma-b12-inchworm-crawl-arch calc(var(--loader-speed, 1s) * 3) ease-in-out infinite; }
.darma-loader-darma-b12-inchworm-crawl span { position: absolute; bottom: 4%; width: 12%; height: calc(var(--loader-size, 116px) * .12); border-radius: 50%; background: var(--accent); animation: darma-loader-darma-b12-inchworm-crawl-foot-back calc(var(--loader-speed, 1s) * 3) ease-in-out infinite; }
.darma-loader-darma-b12-inchworm-crawl span:nth-child(3) { animation-name: darma-loader-darma-b12-inchworm-crawl-foot-front; }
@keyframes darma-loader-darma-b12-inchworm-crawl-arch { 0% { left: 6%; width: 24%; height: 62%; } 25% { left: 6%; width: 58%; height: 30%; } 50% { left: 40%; width: 24%; height: 62%; } 75% { left: 6%; width: 58%; height: 30%; } 100% { left: 6%; width: 24%; height: 62%; } }
@keyframes darma-loader-darma-b12-inchworm-crawl-foot-back { 0%, 25% { left: 4%; } 50% { left: 38%; } 75%, 100% { left: 4%; } }
@keyframes darma-loader-darma-b12-inchworm-crawl-foot-front { 0% { left: 22%; } 25%, 75% { left: 56%; } 100% { left: 22%; } }

